    private static void Require(bool value, string why)
    { if (!value) throw new InvalidOperationException(why); }
    private static string Hash(byte[] bytes) => Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
    private static int Align(int value, int alignment) => checked((value + alignment - 1) / alignment * alignment);
    private static int Read32(byte[] b, int p) => BinaryPrimitives.ReadInt32LittleEndian(b.AsSpan(p, 4));
    private static void Write32(byte[] b, int p, int value) => BinaryPrimitives.WriteInt32LittleEndian(b.AsSpan(p, 4), value);
    private static int FileOffset(PEHeaders h, int rva)
    {
        var s = h.SectionHeaders.Single(s => rva >= s.VirtualAddress && rva < checked(s.VirtualAddress + s.SizeOfRawData));
        return checked(s.PointerToRawData + rva - s.VirtualAddress);
    }

    private sealed class IL
    {
        private readonly List<byte> bytes = [];
        private readonly Dictionary<string, int> labels = [];
        private readonly List<(int At, int End, string Label)> branches = [];
        public IL Op(params byte[] op) { bytes.AddRange(op); return this; }
        private IL I32(int value) { bytes.AddRange(BitConverter.GetBytes(value)); return this; }
        public IL MethodAddress(int token) => Op(0xFE,0x06).I32(token);
        public int OffsetOf(string name) => labels[name];
        public IL Ref(byte op, int token) => Op(op).I32(token);
        public IL ArgAddress(int n) => Op(0x0F, checked((byte)n));
        public IL Arg(int n) => n < 4 ? Op((byte)(2 + n)) : Op(0x0E, checked((byte)n));
        public IL Load(int n) => n < 4 ? Op((byte)(6 + n)) : Op(0x11, checked((byte)n));
        public IL Store(int n) => n < 4 ? Op((byte)(10 + n)) : Op(0x13, checked((byte)n));
        public IL Address(int n) => Op(0x12, checked((byte)n));
        public IL Integer(int value) => value >= -1 && value <= 8 ? Op((byte)(22 + value)) : Op(0x20).I32(value);
        public IL Float(float value) => Op(0x22).I32(BitConverter.SingleToInt32Bits(value));
        public IL FieldAddress(int token) => Ref(0x7C, token);
        public IL Field(int token) => Ref(0x7B, token);
        public IL Set(int token) => Ref(0x7D, token);
        public IL Static(int token) => Ref(0x7E, token);
        public IL Call(int token) => Ref(0x28, token);
        public IL Virtual(int token) => Ref(0x6F, token);
        public IL New(int token) => Ref(0x73, token);
        public IL Label(string name) { labels.Add(name, bytes.Count); return this; }
        public IL Branch(byte op, string name)
        {
            Require((op is >= 0x38 and <= 0x44) || op == 0xDD, "Use long branch encodings");
            Op(op); int at = bytes.Count; I32(0); branches.Add((at, bytes.Count, name)); return this;
        }
        public byte[] Finish()
        {
            var output = bytes.ToArray();
            foreach (var (at, end, label) in branches) Write32(output, at, checked(labels[label] - end));
            return output;
        }
    }

