            s.SectionCharacteristics == (SectionCharacteristics)0x40000040, "Pinned read-only EOF section");
        int sh = h.PEHeaderStartOffset + h.CoffHeader.SizeOfOptionalHeader + (h.CoffHeader.NumberOfSections - 1) * 40;
        Write32(image, sh + 8, checked(meaningfulEnd - s.PointerToRawData));
        Write32(image, sh + 16, image.Length - s.PointerToRawData);
        Write32(image, h.PEHeaderStartOffset + 8,
            checked(p.SizeOfInitializedData + image.Length - s.PointerToRawData - s.SizeOfRawData));
        Write32(image, h.PEHeaderStartOffset + 56,
            Align(checked(s.VirtualAddress + meaningfulEnd - s.PointerToRawData), p.SectionAlignment));
        Write32(image, h.PEHeaderStartOffset + 64, 0);
    }

    private static byte[] AppendBody(byte[] image, int token, byte[] code, int maxStack, int localToken, out object evidence)
    {
        using var pe = new PEReader(new MemoryStream(image, false)); var h = pe.PEHeaders;
        var md = pe.GetMetadataReader(); var m = md.GetMethodDefinition(MetadataTokens.MethodDefinitionHandle(token & 0xFFFFFF));
        var old = pe.GetMethodBody(m.RelativeVirtualAddress); Require(old.ExceptionRegions.Length == 0, "No discarded EH");
        int at = Align(image.Length, 4), ehSize = FinallySectionSize(token);
        int ehAt = Align(checked(at + 12 + code.Length),4);
        int end = ehSize==0 ? checked(at+12+code.Length) : checked(ehAt+ehSize);
        byte[] output = new byte[Align(end, h.PEHeader!.FileAlignment)]; image.CopyTo(output, 0);
        int rva = checked(h.SectionHeaders.Last().VirtualAddress + at - h.SectionHeaders.Last().PointerToRawData);
        BinaryPrimitives.WriteUInt16LittleEndian(output.AsSpan(at, 2), (ushort)(0x3003 | (ehSize!=0 ? 8 : 0) | (old.LocalVariablesInitialized || localToken != 0 ? 0x10 : 0)));
        BinaryPrimitives.WriteUInt16LittleEndian(output.AsSpan(at + 2, 2), checked((ushort)maxStack));
        Write32(output, at + 4, code.Length); Write32(output, at + 8, localToken == 0 ? MetadataTokens.GetToken(old.LocalSignature) : localToken);
        code.CopyTo(output, at + 12);
        if(ehSize!=0)WriteFinallySection(output,ehAt,token,code.Length);
        int row = FileOffset(h, h.CorHeader!.MetadataDirectory.RelativeVirtualAddress) +
            md.GetTableMetadataOffset(TableIndex.MethodDef) + ((token & 0xFFFFFF) - 1) * md.GetTableRowSize(TableIndex.MethodDef);
        Require(Read32(output, row) == m.RelativeVirtualAddress, "MethodDef RVA column");
        Write32(output, row, rva); ExtendReadonlySection(output, h, end);
        evidence = new { token = $"0x{token:X8}", old_rva = m.RelativeVirtualAddress, new_rva = rva,
            il_bytes = code.Length, il_sha256 = Hash(code), max_stack = maxStack, appended_finally_clauses = ehSize==0?0:FinallyBodies[token].Length,
            old_local_signature = $"0x{MetadataTokens.GetToken(old.LocalSignature):X8}",
            new_local_signature = $"0x{(localToken == 0 ? MetadataTokens.GetToken(old.LocalSignature) : localToken):X8}", old_slot_preserved = true };
        return output;
    }

