        string input = Path.GetFullPath(args[0]), output = Path.GetFullPath(args[1]), report = Path.GetFullPath(args[2]);
        Require(!File.Exists(output) && !File.Exists(report) && input != output && input != report && output != report,
            "Fresh distinct output paths");
        byte[] before = File.ReadAllBytes(input);
        Require(ParentSha.Length == 64 && ParentBytes > 0, "Reviewed Native93 aggregate parent binding");
        Require(before.Length == ParentBytes && Hash(before) == ParentSha, "Exact reviewed Native93 input only");
        using var pe = new PEReader(new MemoryStream(before, false)); var h = pe.PEHeaders; var md = pe.GetMetadataReader();
        Require(h.PEHeader!.CertificateTableDirectory.Size == 0 && h.CorHeader!.StrongNameSignatureDirectory.Size == 0 &&
            (h.CorHeader.Flags & CorFlags.StrongNameSigned) == 0, "Unsigned input");
